// The mock core only builds on Unix; on Windows the core scenarios are skipped.
#![cfg_attr(not(unix), allow(unused_imports, dead_code))]
// `std::env::set_var` is `unsafe` (edition 2024): the mock core reads its protocol with getenv().
#![allow(unsafe_code)]
//! 4.0 game folders (design v4.0 §3.2, §10 n° 4) on folders generated by `tests/tools/mkdos.py`: snapshot through
//! the public API (reproducible, source untouched), then `ContentSpec::Folder`, `start`, homonyms,
//! `reset_with_keys` and analog sticks against the mock core (`MOCK_RESET_KEYS`, `MOCK_ANALOG`). The `MOCK_*`
//! variables are process-global: the core scenarios run in sequence inside a single test.

#[path = "../../../tests/support/mock_core.rs"]
mod mock_core;

use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::AtomicBool;

use emu_runtime::{
    AnalogStick, CollectSink, ContentSpec, Emulator, EmulatorOptions, InputBackend, InputFrame,
    JoypadButton, NullInput, RetroKey, RuntimeError, ScriptedInput, SnapshotLimits, SnapshotStatus,
    core_id_from_path, snapshot_folder, snapshot_path, snapshot_status,
};

const FOLDERS: [&str; 8] = [
    "hello",
    "menu",
    "bat",
    "multi",
    "longnames",
    "lowercase",
    "nested",
    "empty",
];

/// Writes every mkdos.py case under `out`.
fn mkdos(out: &Path) {
    let script = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/tools/mkdos.py");
    let run = Command::new("python3")
        .arg("-I")
        .arg(script)
        .arg(out)
        .env("SOURCE_DATE_EPOCH", "1700000000")
        .output()
        .expect("python3 is required for the DOS folder tests");
    assert!(
        run.status.success(),
        "mkdos.py failed: {}",
        String::from_utf8_lossy(&run.stderr)
    );
}

/// Relative `/` path ⇒ (bytes, modification time); folders as `name/`.
type Tree = BTreeMap<String, (Vec<u8>, Option<std::time::SystemTime>)>;

fn tree(root: &Path) -> Tree {
    fn visit(root: &Path, dir: &Path, out: &mut Tree) {
        for entry in fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            let rel = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");
            let meta = fs::symlink_metadata(&path).unwrap();
            if meta.is_dir() {
                out.insert(format!("{rel}/"), (Vec::new(), None));
                visit(root, &path, out);
            } else {
                out.insert(rel, (fs::read(&path).unwrap(), meta.modified().ok()));
            }
        }
    }
    let mut out = Tree::new();
    visit(root, root, &mut out);
    out
}

/// Zip entry name ⇒ bytes (folders as `name/` with no bytes).
fn zip_tree(path: &Path) -> BTreeMap<String, Vec<u8>> {
    let mut archive = zip::ZipArchive::new(fs::File::open(path).unwrap()).unwrap();
    let mut out = BTreeMap::new();
    for i in 0..archive.len() {
        let mut entry = archive.by_index(i).unwrap();
        assert_eq!(entry.compression(), zip::CompressionMethod::Stored);
        let mut data = Vec::new();
        entry.read_to_end(&mut data).unwrap();
        out.insert(String::from_utf8(entry.name_raw().to_vec()).unwrap(), data);
    }
    out
}

fn snapshot(dir: &Path, to: &Path) {
    let report = snapshot_folder(
        dir,
        to,
        &SnapshotLimits::DEFAULT,
        &mut |_, _| {},
        &AtomicBool::new(false),
    )
    .unwrap();
    assert!(report.rebuilt);
}

#[test]
fn generated_games_snapshot_reproducibly_and_stay_untouched() {
    let tmp = tempfile::tempdir().unwrap();
    let games = tmp.path().join("dos");
    mkdos(&games);
    for name in FOLDERS {
        let dir = games.join(name);
        let before = tree(&dir);
        let a = tmp.path().join("cache-a").join(format!("{name}.zip"));
        let b = tmp.path().join("cache-b").join(format!("{name}.zip"));
        snapshot(&dir, &a);
        snapshot(&dir, &b);
        assert_eq!(fs::read(&a).unwrap(), fs::read(&b).unwrap(), "{name}");
        assert_eq!(snapshot_status(&dir, &a).unwrap(), SnapshotStatus::Current);
        let files: BTreeMap<String, Vec<u8>> = before
            .iter()
            .map(|(k, (data, _))| (k.clone(), data.clone()))
            .collect();
        assert_eq!(zip_tree(&a), files, "{name}: same names and bytes");
        assert_eq!(tree(&dir), before, "{name}: folder untouched");
    }
}

#[test]
fn generated_game_over_the_limits_is_refused() {
    let tmp = tempfile::tempdir().unwrap();
    let games = tmp.path().join("dos");
    mkdos(&games);
    let to = tmp.path().join("cache/multi.zip");
    let small = SnapshotLimits {
        max_depth: 1,
        ..SnapshotLimits::DEFAULT
    };
    let r = snapshot_folder(
        &games.join("multi"),
        &to,
        &small,
        &mut |_, _| {},
        &AtomicBool::new(false),
    );
    assert!(matches!(
        r,
        Err(RuntimeError::SnapshotTooLarge { limit: 1 })
    ));
    assert!(!to.exists());
}

const VARS: [&str; 2] = ["MOCK_RESET_KEYS", "MOCK_ANALOG"];

fn set_protocol(vars: &[(&str, &str)]) {
    for name in VARS {
        // SAFETY: the only test of this binary touching the environment; the other tests never read it.
        unsafe { std::env::remove_var(name) };
    }
    for (name, value) in vars {
        // SAFETY: as above.
        unsafe { std::env::set_var(name, value) };
    }
}

struct Env {
    root: PathBuf,
}

impl Env {
    fn new(name: &str) -> Self {
        let root = mock_core::output_dir().join("emu-runtime-dos").join(name);
        let _ = fs::remove_dir_all(&root);
        mkdos(&root.join("dos"));
        Self { root }
    }

    fn options(&self) -> EmulatorOptions {
        let data = self.root.join("data");
        EmulatorOptions {
            system_dir: data.join("system"),
            save_dir: data.join("saves"),
            cache_dir: data.join("cache"),
            provide_vfs: false,
            state_dir: data.join("states"),
            assets_dir: data.join("assets"),
            core_variables: Vec::new(),
            restore_added_disks: false,
            core_save_scope: emu_runtime::SaveScope::Core,
            fastforward_override: false,
            variable_state_size: false,
            port_devices: Vec::new(),
        }
    }

    fn game(&self, name: &str) -> PathBuf {
        self.root.join("dos").join(name)
    }

    fn cache(&self, lib: &Path) -> PathBuf {
        self.root.join("data/cache").join(core_id_from_path(lib))
    }
}

fn folder(dir: &Path, start: Option<&str>) -> ContentSpec {
    ContentSpec::Folder {
        dir: dir.to_path_buf(),
        name: dir.file_name().unwrap().to_string_lossy().into_owned(),
        start: start.map(str::to_owned),
    }
}

/// Copies a generated folder elsewhere (homonyms).
fn copy_dir(from: &Path, to: &Path) {
    for (rel, (data, _)) in tree(from) {
        let path = to.join(&rel);
        if rel.ends_with('/') {
            fs::create_dir_all(path).unwrap();
        } else {
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, data).unwrap();
        }
    }
}

#[cfg(unix)]
#[test]
fn folder_games_on_mock_core() {
    let lib = mock_core::build(mock_core::Variant::Default);
    set_protocol(&[]);
    folder_load_and_start(&lib);
    homonym_folders(&lib);
    reset_with_keys(&lib);
    analog_sticks(&lib);
    set_protocol(&[]);
}

fn folder_load_and_start(lib: &Path) {
    let env = Env::new("load");
    let dir = env.game("multi");
    let before = tree(&dir);
    let emu = Emulator::load_content(lib, folder(&dir, None), env.options()).unwrap();
    let snap = env.cache(lib).join("multi.zip");
    assert_eq!(emu.game_name(), "multi");
    assert_eq!(emu.content_name(), Some("multi"), "stem of the snapshot");
    assert_eq!(
        snapshot_status(&dir, &snap).unwrap(),
        SnapshotStatus::Current
    );
    assert_eq!(zip_tree(&snap).len(), before.len());
    drop(emu);
    assert_eq!(tree(&dir), before, "folder untouched by a session");

    // `start`: checked against the folder, then appended after `#` in upper case. The in-memory mock cannot read
    // `multi.zip#GAME.EXE` (dosbox_pure is `need_fullpath`): the error names the path the core would get.
    let err = Emulator::load_content(lib, folder(&dir, Some("game.exe")), env.options())
        .err()
        .expect("not a file for an in-memory core");
    let expected = format!("{}#GAME.EXE", snap.display());
    assert!(err.to_string().contains(&expected), "{err}");
    for bad in ["README.TXT", "NOPE.EXE", "DATA.EXE", "../GAME.EXE"] {
        let r = Emulator::load_content(lib, folder(&dir, Some(bad)), env.options());
        assert!(
            matches!(&r, Err(RuntimeError::InvalidStart(s)) if s == bad),
            "{bad}: {:?}",
            r.err()
        );
    }
    assert_eq!(tree(&dir), before);
}

fn homonym_folders(lib: &Path) {
    let env = Env::new("homonyms");
    let first = env.root.join("a/GAME");
    let second = env.root.join("b/GAME");
    copy_dir(&env.game("hello"), &first);
    copy_dir(&env.game("menu"), &second);
    let cache = env.cache(lib);

    let emu = Emulator::load_content(lib, folder(&first, None), env.options()).unwrap();
    assert_eq!(emu.game_name(), "GAME");
    assert_eq!(emu.identity().index, 1);
    drop(emu);
    let emu = Emulator::load_content(lib, folder(&second, None), env.options()).unwrap();
    assert_eq!(
        emu.game_name(),
        "GAME (2)",
        "same folder name, another game"
    );
    assert_eq!(emu.content_name(), Some("GAME (2)"));
    assert!(emu.identity().core_save_dir.ends_with("GAME (2)"));
    drop(emu);
    assert_eq!(
        zip_tree(&cache.join("GAME.zip")).keys().collect::<Vec<_>>(),
        ["HELLO.COM"]
    );
    assert_eq!(
        zip_tree(&cache.join("GAME (2).zip"))
            .keys()
            .collect::<Vec<_>>(),
        ["MENU1.COM", "MENU2.COM"]
    );
    assert_eq!(
        snapshot_path(&cache, "GAME (2)"),
        cache.join("GAME (2).zip")
    );

    // Same folder again, the same folder with a start program, and the first one moved: identities kept.
    let emu = Emulator::load_content(lib, folder(&first, None), env.options()).unwrap();
    assert_eq!(emu.game_name(), "GAME");
    drop(emu);
    let err = Emulator::load_content(lib, folder(&second, Some("MENU2.COM")), env.options())
        .err()
        .unwrap();
    assert!(err.to_string().contains("GAME (2).zip#MENU2.COM"), "{err}");
    let moved = env.root.join("c/GAME");
    fs::create_dir_all(moved.parent().unwrap()).unwrap();
    fs::rename(&first, &moved).unwrap();
    let emu = Emulator::load_content(lib, folder(&moved, None), env.options()).unwrap();
    assert_eq!(emu.game_name(), "GAME", "a moved folder keeps its saves");
}

fn mock_file(emu: &Emulator, name: &str) -> String {
    fs::read_to_string(emu.identity().core_save_dir.join(name)).unwrap_or_default()
}

fn reset_with_keys(lib: &Path) {
    set_protocol(&[("MOCK_RESET_KEYS", "1")]);
    let env = Env::new("reset");
    let mut emu =
        Emulator::load_content(lib, folder(&env.game("hello"), None), env.options()).unwrap();
    let lshift = RetroKey::new(304).unwrap();
    let a = RetroKey::new(97).unwrap();
    emu.reset_with_keys(&[lshift]);
    assert_eq!(
        mock_file(&emu, "mock-reset.txt"),
        "resets=1\nshift=1\ndown=304\n"
    );
    assert!(emu.uses_keyboard(), "the core polled the keyboard");
    // `Core::reset` installs no handler: nothing reads as pressed.
    emu.reset();
    assert_eq!(
        mock_file(&emu, "mock-reset.txt"),
        "resets=2\nshift=0\ndown=\n"
    );

    // Keys held in the last frame do not leak into the reset: only `held` is pressed.
    let mut input = ScriptedInput::new().key(a, 0..1);
    emu.run_frame(&mut input, &mut CollectSink::default())
        .unwrap();
    emu.reset_with_keys(&[a]);
    let only_a = mock_file(&emu, "mock-reset.txt");
    assert!(
        only_a.contains("shift=0\n") && only_a.contains("down=97\n"),
        "{only_a}"
    );
    emu.reset_with_keys(&[]);
    let none = mock_file(&emu, "mock-reset.txt");
    assert!(
        none.contains("shift=0\n") && none.contains("down=\n"),
        "{none}"
    );
}

/// Port 1: left stick, right stick and R2 held.
struct Sticks;

impl InputBackend for Sticks {
    fn poll(&mut self, _frame_index: u64, state: &mut InputFrame) {
        let pad = &mut state.pads[1];
        pad.set_analog(AnalogStick::Left, 1000, -2000);
        pad.set_analog(AnalogStick::Right, i16::MIN, i16::MAX);
        pad.set(JoypadButton::R2, true);
    }
}

fn analog_sticks(lib: &Path) {
    set_protocol(&[("MOCK_ANALOG", "1")]);
    let env = Env::new("analog");
    let mut emu =
        Emulator::load_content(lib, folder(&env.game("hello"), None), env.options()).unwrap();
    emu.run_frame(&mut Sticks, &mut CollectSink::default())
        .unwrap();
    let text = mock_file(&emu, "mock-analog.txt");
    let mut buttons = vec!["0"; 16];
    buttons[JoypadButton::R2.id() as usize] = "32767";
    let expected = format!(
        "port=1\nleft=1000,-2000\nright=-32768,32767\nbuttons={}\n",
        buttons.join(",")
    );
    assert_eq!(text, expected);
    // Keyboard only (nothing set): sticks centred.
    emu.run_frame(&mut NullInput, &mut CollectSink::default())
        .unwrap();
    let text = mock_file(&emu, "mock-analog.txt");
    assert!(text.contains("left=0,0\nright=0,0\n"), "{text}");
}
